"""
    x = 5
          L      R
      1 3 4      10 10
   arr[i] <5 |   5 <= arr[i]


   x = 2
      L              R
      1              3 4 10 10
   arr[0..L] < 2 |   2 <= arr[R..N]
    """
def bisect_left(arr: Any, x: Any) -> object {
    N = len(arr);
    l = -1;
    r = N;
    while (r > (l + 1)) {
        m = (l + r) // 2;
        if (arr[m] < x) {
            l = m;
        } else {
            r = m;
        }
    }
    return l;
}

